from torch import nn
import torch
import numpy as np
import os
from scipy.io import loadmat

class ADMMDual(nn.Module):
    def __init__(self,mat_dim = 6,input_dim = 2,num_steps:int=10,problem_parameters:dict={}):
        super().__init__()
        # set the datatype of the parameters to be uniform in the whole network
        self.dtypus = problem_parameters["dtype"]
        # load the dpc files generated by matlab
        to_load = "QP_parameters_SS.mat"
        own_dic = os.path.dirname(os.path.dirname(os.path.realpath(__file__)))
        dpc_parameters = loadmat(os.path.join(own_dic,f"mat_files_{problem_parameters["N"]}",to_load))        
        self.n_regios = num_steps
        # Setup the gradients
        G =  dpc_parameters["G"]
        H = dpc_parameters["H"]
        AA = dpc_parameters["Kx"]
        BB = dpc_parameters["Ku"]
        self.N = problem_parameters["N"]
        self.m = problem_parameters["m"]
        self.n = problem_parameters["n"]
        Hinv = np.linalg.inv(H)
        E = dpc_parameters["E"]
        F = dpc_parameters["F"]
        d = dpc_parameters["d"]
        GHG = G@Hinv@G.T
        EGHF = E+G@Hinv@F
        Uz = d[0:Hinv.shape[0],0]
        Lz = d[Hinv.shape[0]:,0]
        # a_std = 1/np.max(np.linalg.eigh(GHG).eigenvalues)
        eigs = np.linalg.eigh(GHG).eigenvalues
        tol = 1e-3
        alphar = 0.2
        a_std = np.sqrt((np.max(eigs[eigs>tol])**(alphar))*(np.min(eigs[eigs>tol])**(1-alphar)))
        a_in = np.log(np.exp(a_std)-1)
        M = np.linalg.inv(GHG+a_std*np.eye(GHG.shape[0]))
        # a_in = np.log(np.exp(a_std)-1)
        self.dual_n_steps = 1
        GGT = G@G.T
        a_ggt = 1/np.max(np.linalg.eigh(GGT).eigenvalues)
        self.M1 =   nn.ParameterList(nn.Parameter(torch.tensor(M               , dtype=self.dtypus),requires_grad= True) for i in range(num_steps))
        self.M2 =   nn.ParameterList(nn.Parameter(torch.tensor(-M@EGHF         , dtype=self.dtypus),requires_grad= True) for i in range(num_steps))
        self.M3 =   nn.ParameterList(nn.Parameter(torch.tensor(-M@d.reshape(-1), dtype=self.dtypus),requires_grad= True) for i in range(num_steps))
        self.rhos = nn.ParameterList(nn.Parameter(torch.tensor(a_in            , dtype=self.dtypus),requires_grad= True) for i in range(num_steps))
        self.G_implicit = nn.Parameter(torch.zeros(EGHF.shape         , dtype=self.dtypus),requires_grad= True)
        self.h_implicit = nn.Parameter(torch.zeros(M.shape[0]         , dtype=self.dtypus),requires_grad= True)
        self.register_buffer("Hinv",   torch.tensor(Hinv, dtype = self.dtypus))
        self.register_buffer("GGT",    torch.tensor(GGT  ,dtype = self.dtypus))
        self.register_buffer("a_G",    torch.tensor(a_ggt,dtype = self.dtypus))
        self.register_buffer("AA",     torch.tensor(AA,   dtype = self.dtypus))
        self.register_buffer("BB",     torch.tensor(BB,   dtype = self.dtypus))
        self.register_buffer("d",      torch.tensor(d,    dtype = self.dtypus))
        self.register_buffer("E",      torch.tensor(E,    dtype = self.dtypus))
        self.register_buffer("F_final",torch.tensor(F,    dtype = self.dtypus))
        self.register_buffer("H_final",torch.tensor(H,    dtype = self.dtypus))
        self.register_buffer("G",      torch.tensor(G,    dtype = self.dtypus))
        self.register_buffer("Lz",     torch.tensor(Lz,   dtype = self.dtypus))
        self.register_buffer("Uz",     torch.tensor(Uz,   dtype = self.dtypus))
        return

    def forward(self, xy: torch.Tensor):
        Hinv = self.Hinv.to(xy)
        G    = self.G.to(xy)
        GGT  = self.GGT.to(xy)
        E    = self.E.to(xy)
        F_final    = self.F_final.to(xy)
        H_final    = self.H_final.to(xy)
        d    = self.d.to(xy)
        Lz   = self.Lz.to(xy)
        Uz   = self.Uz.to(xy)
        a_G  = self.a_G.to(xy)
        
        # Standard ADMM scheme:
        batch_size = xy.shape[0]
        lam_shape = G.shape[0]
        z_shape = G.shape[1]
        yk =  xy@self.G_implicit.T + self.h_implicit#torch.zeros((batch_size,lam_shape), device=xy.device, dtype=xy.dtype)
        zk =  torch.relu(xy@self.G_implicit.T + self.h_implicit)#torch.zeros((batch_size,lam_shape), device=xy.device, dtype=xy.dtype)
        muk = torch.zeros((batch_size,lam_shape), device=xy.device, dtype=xy.dtype)
        
        zk_hat = torch.zeros((batch_size,z_shape), device=xy.device, dtype=xy.dtype)
        zk_tru = torch.zeros((batch_size,z_shape), device=xy.device, dtype=xy.dtype)
        y_list = [yk]
        z_list = [zk]
        mu_list= [muk]
        z_hat_list = [zk_hat]
        z_tru_list = [zk_tru]
        Fx = xy @ F_final.T
        for j in range(0,self.n_regios):
            rhok = torch.nn.functional.softplus(self.rhos[j])
            # Update first variable
            M1_sym = 0.5*(self.M1[j]+self.M1[j].T)
            ykp1  =   (rhok*zk - muk)@M1_sym + xy@self.M2[j].T + self.M3[j]
            # Update second variable
            zkp1  = torch.relu( ykp1 + (1/rhok)*muk)
            # Update dual variable
            mukp1 = muk + rhok*(ykp1-zkp1)

            # y_list.append(ykp1)
            z_list.append(zkp1)
            # mu_list.append(mukp1)

            yk = ykp1
            zk = zkp1
            muk = mukp1
            
            Glam = torch.matmul(G.T, zkp1.T)
            rhs = Fx.T + Glam
            zk_hat = -torch.matmul(Hinv, rhs).T
            zk_tru = torch.clamp(input= zk_hat,min=-Lz,max=Uz)

            z_hat_list.append(zk_hat)
            z_tru_list.append(zk_tru)

        # y_stck = torch.stack(y_list, dim=-1)
        z_stck = torch.stack(z_list, dim=-1)
        # mu_stck= torch.stack(mu_list, dim=-1)
        z_poss = torch.stack(z_hat_list, dim=-1)
        z_full = torch.stack(z_tru_list, dim=-1)
        return z_full,z_poss,z_stck